body.script:
//
(function(){var box=document.getElementById('eh-latest-posts');if(!box)return;var s=document.createElement('script');window.ehLatest=function(feed){var e=feed.feed&&feed.feed.entry?feed.feed.entry:[];if(!e.length){box.innerHTML='<div class="latest-loading">No recent posts found.</div>';return}var h='';for(var i=0;i<Math.min(e.length,6);i++){var p=e[i],t=(p.title&&p.title.$t)||'English Hub resource',u='#',d='';for(var j=0;j<(p.link||[]).length;j++){if(p.link[j].rel==='alternate'){u=p.link[j].href;break}}if(p.published&&p.published.$t)d=new Date(p.published.$t).toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'});var c=(p.category&&p.category[0]&&p.category[0].term)||'English Hub';h+='<a class="latest-card" href="'+u+'"><span class="latest-label">'+c.replace(/&/g,'&amp;')+'</span><span class="latest-title">'+t.replace(/&/g,'&amp;')+'</span>'+(d?'<span class="latest-date">'+d+'</span>':'')+'</a>'}box.innerHTML=h};s.src='/feeds/posts/default?alt=json-in-script&max-results=6&callback=ehLatest';document.body.appendChild(s)})();
//
